const flatEffects = (): Fields[] => [...Object.values(EFFECTS).flat(), ...COMPOSITES];

// Builds the synthetic pool. Ids are negative so they never collide with real card ids.
export function syntheticCards(): Card[] {
  const cards: Card[] = [];
  let next = -1;
  const add = (type: Card['type'], nom: string, fields: Fields) => {
    cards.push({ id: next, type, nom, ...fields });
    next -= 1;
  };

  // Fighters: neutral stats, so effects rather than raw stats decide the combat.
  const fighter = (nom: string, fields: Fields, atq = 18, pv = 90) =>
    add('combattant', nom, { atq, pv, passif: null, ultime: null, ...fields });

  fighter('S-plain', {});
  fighter('S-tank', {}, 6, 400);
  PASSIVES.forEach((p, i) => fighter(`S-passive-${i}-${String(p['type'])}`, { passif: p }));
  PASSIVE_COMBOS.forEach((combo, i) => fighter(`S-combo-${i}`, { passif: { briques: combo } }));
  flatEffects().forEach((effect, i) => {
    const trigger = ULTIMATE_TRIGGERS[i % ULTIMATE_TRIGGERS.length];
    if ('type' in effect)
      fighter(`S-ultimate-${i}-${String(effect['type'])}`, { ultime: { ...effect, ...trigger } });
  });

  flatEffects().forEach((effect, i) => add('magie', `S-magic-${i}`, { effet: effect }));

  flatEffects().forEach((effect, i) => {
    const condition = TRAP_CONDITIONS[i % TRAP_CONDITIONS.length];
    add('piege', `S-trap-${i}`, {
      effet: { condition, effet: effect, declenchements: 1 + (i % 3) },
    });
  });
  // Every condition at least once with a cheap, visible effect.
  TRAP_CONDITIONS.forEach((condition, i) =>
    add('piege', `S-trap-cond-${i}`, {
      effet: { condition, effet: { type: 'degats', val: 8 }, declenchements: 2 },
    }),
  );
  // Trap chains: a heal-triggered trap next to a trap that heals.
  add('piege', 'S-trap-heal', {
    effet: {
      condition: { type: 'adv_attaque', coups: 1 },
      effet: { type: 'soin', val: 10, u: 'pct' },
      declenchements: 3,
    },
  });
  add('piege', 'S-trap-on-heal', {
    effet: {
      condition: { type: 'adv_soigne' },
      effet: { type: 'soin', val: 5, u: 'pct' },
      declenchements: 3,
    },
  });

  return cards;
}
